import type { HeadAttrsConfig } from '@vuepress/shared'

/**
 * Escape a string to be used as an html attribute value
 *
 * The `&` must be escaped first, otherwise the entities generated by the
 * following replacements would be escaped again.
 */
const escapeAttributeValue = (value: string): string =>
  value
    .replaceAll('&', '&amp;')
    .replaceAll('"', '&quot;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')

/**
 * Render head attrs config to string
 *
 * Attributes are rendered by string concatenation on the server side, so their
 * values need to be escaped manually to avoid breaking out of the attribute.
 * On the client side, `setAttribute` in `packages/client/src/setupUpdateHead.ts`
 * is used instead, which stores the raw value and handles escaping safely, so
 * the escaped server output still results in the same attribute value after
 * being parsed by the browser.
 */
export const renderHeadAttrs = (attrs: HeadAttrsConfig): string =>
  Object.entries(attrs)
    .filter((item): item is [string, string | true] => item[1] !== false)
    .map(([key, value]) =>
      value === true ? ` ${key}` : ` ${key}="${escapeAttributeValue(value)}"`,
    )
    .join('')
